PRAGMA foreign_keys = ON;
CREATE TABLE user (id TEXT PRIMARY KEY, name TEXT NOT NULL, email TEXT NOT NULL UNIQUE, emailVerified INTEGER NOT NULL DEFAULT 0, image TEXT, createdAt INTEGER NOT NULL, updatedAt INTEGER NOT NULL, username TEXT UNIQUE, displayUsername TEXT, role TEXT NOT NULL DEFAULT 'vendedor', active INTEGER NOT NULL DEFAULT 1, mustChangePassword INTEGER NOT NULL DEFAULT 1, banned INTEGER DEFAULT 0, banReason TEXT, banExpires INTEGER);
CREATE TABLE session (id TEXT PRIMARY KEY, expiresAt INTEGER NOT NULL, token TEXT NOT NULL UNIQUE, createdAt INTEGER NOT NULL, updatedAt INTEGER NOT NULL, ipAddress TEXT, userAgent TEXT, userId TEXT NOT NULL REFERENCES user(id) ON DELETE CASCADE, impersonatedBy TEXT);
CREATE INDEX session_user ON session(userId);
CREATE TABLE account (id TEXT PRIMARY KEY, accountId TEXT NOT NULL, providerId TEXT NOT NULL, userId TEXT NOT NULL REFERENCES user(id) ON DELETE CASCADE, accessToken TEXT, refreshToken TEXT, idToken TEXT, accessTokenExpiresAt INTEGER, refreshTokenExpiresAt INTEGER, scope TEXT, password TEXT, createdAt INTEGER NOT NULL, updatedAt INTEGER NOT NULL);
CREATE INDEX account_user ON account(userId);
CREATE TABLE verification (id TEXT PRIMARY KEY, identifier TEXT NOT NULL, value TEXT NOT NULL, expiresAt INTEGER NOT NULL, createdAt INTEGER NOT NULL, updatedAt INTEGER NOT NULL);
CREATE INDEX verification_identifier ON verification(identifier);
CREATE TABLE rateLimit (id TEXT PRIMARY KEY, key TEXT NOT NULL UNIQUE, count INTEGER NOT NULL, lastRequest INTEGER NOT NULL);
CREATE TABLE clients (id TEXT PRIMARY KEY, code TEXT NOT NULL UNIQUE, name TEXT NOT NULL, rif TEXT NOT NULL DEFAULT '', contact TEXT NOT NULL DEFAULT '', phone TEXT NOT NULL DEFAULT '', address TEXT NOT NULL DEFAULT '', zone TEXT NOT NULL DEFAULT '', seller_id TEXT REFERENCES user(id), active INTEGER NOT NULL DEFAULT 1 CHECK(active IN(0,1)), geo_json TEXT, geo_updated_by TEXT REFERENCES user(id), slots_json TEXT NOT NULL DEFAULT '[]', recurrence TEXT NOT NULL DEFAULT 'semanal' CHECK(recurrence IN('semanal','quincenal','mensual')), recurrence_start TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE UNIQUE INDEX client_rif ON clients(rif) WHERE rif <> '';
CREATE INDEX client_assignment ON clients(seller_id,active,name);
CREATE VIRTUAL TABLE clients_fts USING fts5(name,code,rif,zone,content=clients,content_rowid=rowid,tokenize='unicode61 remove_diacritics 2');
CREATE TRIGGER clients_ai AFTER INSERT ON clients BEGIN INSERT INTO clients_fts(rowid,name,code,rif,zone) VALUES(new.rowid,new.name,new.code,new.rif,new.zone); END;
CREATE TRIGGER clients_ad AFTER DELETE ON clients BEGIN INSERT INTO clients_fts(clients_fts,rowid,name,code,rif,zone) VALUES('delete',old.rowid,old.name,old.code,old.rif,old.zone); END;
CREATE TRIGGER clients_au AFTER UPDATE ON clients BEGIN INSERT INTO clients_fts(clients_fts,rowid,name,code,rif,zone) VALUES('delete',old.rowid,old.name,old.code,old.rif,old.zone); INSERT INTO clients_fts(rowid,name,code,rif,zone) VALUES(new.rowid,new.name,new.code,new.rif,new.zone); END;
CREATE TABLE products (id TEXT PRIMARY KEY, sku TEXT NOT NULL UNIQUE, name TEXT NOT NULL, price_usd TEXT NOT NULL, active INTEGER NOT NULL DEFAULT 1 CHECK(active IN(0,1)), created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE exchange_rates (id TEXT PRIMARY KEY, currency TEXT NOT NULL CHECK(currency IN('COP','VES')), rate TEXT NOT NULL, created_at TEXT NOT NULL, created_by TEXT NOT NULL REFERENCES user(id));
CREATE INDEX rates_latest ON exchange_rates(currency,created_at DESC,id);
CREATE TABLE routes (id TEXT PRIMARY KEY, name TEXT NOT NULL, seller_id TEXT NOT NULL REFERENCES user(id), date TEXT NOT NULL, created_by TEXT NOT NULL REFERENCES user(id), created_at TEXT NOT NULL);
CREATE INDEX route_seller_date ON routes(seller_id,date);
CREATE TABLE orders (number INTEGER PRIMARY KEY AUTOINCREMENT, id TEXT NOT NULL UNIQUE, client_id TEXT NOT NULL REFERENCES clients(id), author_id TEXT NOT NULL REFERENCES user(id), currency TEXT NOT NULL CHECK(currency IN('USD','COP','VES')), rate TEXT NOT NULL, rate_id TEXT REFERENCES exchange_rates(id), total_minor INTEGER NOT NULL CHECK(total_minor>=0), total_usd_minor INTEGER NOT NULL CHECK(total_usd_minor>=0), units INTEGER NOT NULL CHECK(units>0), status TEXT NOT NULL DEFAULT 'pendiente' CHECK(status IN('pendiente','validado','en_preparacion','listo','anulado')), notes TEXT NOT NULL DEFAULT '', client_snapshot TEXT NOT NULL, idempotency_key TEXT NOT NULL, request_hash TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, sync_status TEXT NOT NULL DEFAULT 'no_configurado', UNIQUE(author_id,idempotency_key));
CREATE INDEX order_author_date ON orders(author_id,created_at DESC);
CREATE INDEX order_client_date ON orders(client_id,created_at DESC);
CREATE TABLE order_items (id TEXT PRIMARY KEY, order_id TEXT NOT NULL REFERENCES orders(id) ON DELETE CASCADE, product_id TEXT NOT NULL REFERENCES products(id), name TEXT NOT NULL, sku TEXT NOT NULL, quantity INTEGER NOT NULL CHECK(quantity>0), price_usd TEXT NOT NULL, unit_minor INTEGER NOT NULL CHECK(unit_minor>=0), subtotal_minor INTEGER NOT NULL CHECK(subtotal_minor>=0), UNIQUE(order_id,product_id));
CREATE TABLE commands (id TEXT PRIMARY KEY, order_id TEXT NOT NULL UNIQUE REFERENCES orders(id), status TEXT NOT NULL DEFAULT 'pendiente' CHECK(status IN('pendiente','en_preparacion','listo')), created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE visits (id TEXT PRIMARY KEY, client_id TEXT NOT NULL REFERENCES clients(id), seller_id TEXT NOT NULL REFERENCES user(id), scheduled_at TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'programada' CHECK(status IN('programada','con_pedido','sin_pedido')), notes TEXT NOT NULL DEFAULT '', order_id TEXT UNIQUE REFERENCES orders(id), route_id TEXT REFERENCES routes(id), route_position INTEGER, created_at TEXT NOT NULL, completed_at TEXT);
CREATE INDEX visit_seller_date ON visits(seller_id,scheduled_at);
CREATE UNIQUE INDEX visit_no_duplicate ON visits(client_id,seller_id,scheduled_at);
CREATE TABLE audit_log (id TEXT PRIMARY KEY, actor_id TEXT NOT NULL REFERENCES user(id), action TEXT NOT NULL, entity_type TEXT NOT NULL, entity_id TEXT NOT NULL, details_json TEXT NOT NULL DEFAULT '{}', created_at TEXT NOT NULL);
CREATE INDEX audit_entity ON audit_log(entity_type,entity_id,created_at);
CREATE TRIGGER order_scope BEFORE INSERT ON orders BEGIN
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM clients c JOIN user u ON u.id=new.author_id WHERE c.id=new.client_id AND c.active=1 AND u.active=1 AND u.banned=0 AND (u.role='administracion' OR (u.role='vendedor' AND c.seller_id=u.id AND trim(c.rif)<>'' AND trim(c.contact)<>'' AND trim(c.phone)<>'' AND trim(c.address)<>'' AND c.geo_json IS NOT NULL))) THEN RAISE(ABORT,'ORDER_CLIENT_SCOPE') END;
END;
CREATE TRIGGER command_requires_validation BEFORE INSERT ON commands BEGIN SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM orders WHERE id=new.order_id AND status='validado') THEN RAISE(ABORT,'ORDER_NOT_VALIDATED') END; END;
